import Testing
import Foundation
@testable import OpenMDict

/// Lookups that match several records (Tests/Fixtures/homographs.mdx,
/// regenerated by make-fixture.py).
@Suite(.serialized)
struct HomographLookupTests {

    nonisolated(unsafe) static var _reader: MDictReader?

    static func reader() throws -> MDictReader {
        if let r = _reader { return r }
        let path = TestFixtures.fixturesDirectory.appendingPathComponent("homographs.mdx").path
        let r = try MDictReader(path: path)
        _reader = r
        return r
    }

    /// mdict-utils stores each record with its trailing newline.
    static func text(_ html: String) -> String {
        html.trimmingCharacters(in: .whitespacesAndNewlines)
    }

    @Test("Records that share a key are all returned, in dictionary order")
    func exactDuplicates() throws {
        let entries = try Self.reader().lookupAll("bank")
        #expect(entries.map { Self.text($0.article.html) } == [
            "<p>bank (1): the side of a river</p>",
            "<p>bank (2): an institution that keeps money</p>",
        ])
    }

    @Test("Case variants: the exact-case record comes first, then the others")
    func caseVariants() throws {
        let reader = try Self.reader()
        #expect(reader.lookupAll("turkey").map(\.key) == ["turkey", "Turkey"])
        #expect(reader.lookupAll("Turkey").map(\.key) == ["Turkey", "turkey"])
        #expect(reader.lookupAll("TURKEY").map(\.key).sorted() == ["Turkey", "turkey"])
    }

    @Test("An article and a redirect under one key: both, the redirect resolved")
    func articleAndRedirect() throws {
        let entries = try Self.reader().lookupAll("sono")
        #expect(entries.map { Self.text($0.article.html) } == [
            "<p>sono: alternative form of suono</p>",
            "<p>essere: to be</p>",
        ])
    }

    @Test("Several keys redirecting to one article yield it once")
    func redirectsToSameArticle() throws {
        let entries = try Self.reader().lookupAll("am")
        #expect(entries.count == 1)
        #expect(entries.first.map { Self.text($0.article.html) } == "<p>be: to exist</p>")
    }

    @Test("lookup() joins the articles with the homograph separator")
    func joinedArticle() throws {
        let entry = try #require(try Self.reader().lookup("bank"))
        #expect(entry.key == "bank")
        let parts = entry.article.html.components(separatedBy: MDictReader.homographSeparator)
        #expect(parts.map(Self.text) == [
            "<p>bank (1): the side of a river</p>",
            "<p>bank (2): an institution that keeps money</p>",
        ])
        let single = try #require(try Self.reader().lookup("single"))
        #expect(!single.article.html.contains(MDictReader.homographSeparator))
        #expect(Self.text(single.article.html) == "<p>single: one only</p>")
    }

    @Test("A typographic apostrophe finds an ASCII-apostrophe key, and the reverse")
    func apostrophes() throws {
        let reader = try Self.reader()
        #expect(reader.lookup("o\u{2019}clock")?.key == "o'clock")
        #expect(reader.lookup("o\u{02BC}clock")?.key == "o'clock")
        #expect(reader.lookup("o'clock")?.key == "o'clock")
        #expect(reader.lookup("rock 'n' roll")?.key == "rock \u{2019}n\u{2019} roll")
        #expect(reader.search(prefix: "o\u{2019}cl") == ["o'clock"])
        #expect(reader.lookup("nothing'here") == nil)
    }

    @Test("Prefix search and lookup find keys written with either apostrophe")
    func mixedApostrophes() throws {
        let reader = try Self.reader()
        #expect(reader.search(prefix: "rapport d'") == ["rapport d'activité", "rapport d\u{2019}étape"])
        #expect(reader.search(prefix: "rapport d\u{2019}") == ["rapport d'activité", "rapport d\u{2019}étape"])
        #expect(reader.lookup("rapport d'étape")?.key == "rapport d\u{2019}étape")
    }

    @Test("One lookup returns at most maxRecordsPerLookup records")
    func cap() throws {
        let reader = try Self.reader()
        #expect(reader.lookupAll("many").count == MDXParser.maxRecordsPerLookup)
        #expect(Self.text(reader.lookupAll("many")[0].article.html) == "<p>many #0</p>")
    }

    @Test("Joined records keep a repeated script or stylesheet only once")
    func scriptsOnce() throws {
        let html = try #require(try Self.reader().lookup("toggle")).article.html
        #expect(html.components(separatedBy: "<script src=\"t.js\"></script>").count == 2)
        #expect(html.components(separatedBy: "<link rel=\"stylesheet\" href=\"t.css\">").count == 2)
        #expect(html.contains("toggle (1)") && html.contains("toggle (2)"))
    }

    @Test("contains() checks keys without loading records; article(at:) reads one record")
    func containsAndPosition() throws {
        let reader = try Self.reader()
        #expect(reader.contains("BANK"))
        #expect(reader.contains("o\u{2019}clock"))
        #expect(!reader.contains("nope"))
        // Every row resolves to exactly one record (a redirect to its target).
        for i in 0..<reader.entryCount {
            let entry = try #require(reader.article(at: i))
            #expect(!entry.article.html.contains(MDictReader.homographSeparator))
            #expect(!entry.article.html.hasPrefix("@@@LINK="))
        }
    }
}
